<script lang="ts">
  import { liveValue } from './live-value';
  export interface Model {
    paper: string; paperName: string; widthCm: number; heightCm: number; width: number; height: number; rawWidthCm: number; rawHeightCm: number; orient: string;
    mt: number; ml: number; current: number; papers: { key: string; name: string }[];
    pages: { objects: number; thumbnail: string }[];
  }
  let { model }: { model: Model } = $props();
  const icons = { up: '<path d="M10 15V5M6 9l4-4 4 4"/>', down: '<path d="M10 5v10M6 11l4 4 4-4"/>', dup: '<path d="M7 7h9v9H7z"/><path d="M4 13V4h9"/>', ins: '<path d="M10 5v10M5 10h10"/>', del: '<path d="M4 5.5h12M8 5.5V3.5h4v2M5.5 5.5l1 12h7l1-12"/>' };
  const round = (n: number) => +n.toFixed(2);
</script>
{#snippet number(key: string, value: number)}<input type="number" data-pp={key} {@attach liveValue(round(value))} step="0.25" min="0">{/snippet}
<h3>Page <small>{model.paperName} · {round(model.widthCm)} × {round(model.heightCm)} cm</small></h3><div class="sec">
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>Paper</label><div class="ctl"><select data-pp="paper" {@attach liveValue(model.paper)}>{#each model.papers as paper}<option value={paper.key}>{paper.name}</option>{/each}</select></div></div>
  {#if model.paper === 'custom'}<div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>Size (cm)</label><div class="ctl">{@render number('w', model.rawWidthCm)}<span class="x">×</span>{@render number('h', model.rawHeightCm)}</div></div>{/if}
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>Orientation</label><div class="ctl seg-ctl"><button data-ppo="portrait" class={model.orient !== 'landscape' ? 'on' : ''} title="Portrait"><svg viewBox="0 0 20 20"><path d="M6 3h8v14H6z"/></svg></button><button data-ppo="landscape" class={model.orient === 'landscape' ? 'on' : ''} title="Landscape"><svg viewBox="0 0 20 20"><path d="M3 6h14v8H3z"/></svg></button></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>Margins</label><div class="ctl">{@render number('mt', model.mt)}{@render number('ml', model.ml)}</div></div><div class="hint-line">Margins (top/bottom · left/right, cm) are guides only: snap to them, or place things right to the edge. Shared with the Document view's page setup.</div></div>
<h3>Pages <small>{model.pages.length} page{model.pages.length > 1 ? 's' : ''} · PgUp / PgDn</small></h3><div class="sec pg-list">{#each model.pages as page, k}<div class={'pg-item' + (k === model.current ? ' on' : '')} data-pg="go" data-k={k} title={'Go to page ' + (k + 1)}><div class="pg-thumb" style={'aspect-ratio:' + model.width + '/' + model.height}>{@html page.thumbnail}</div><div class="pg-meta"><b>Page {k + 1}</b><span>{page.objects ? page.objects + ' object' + (page.objects > 1 ? 's' : '') : 'empty'}</span><div class="pg-acts">{#each [{ key: 'up', at: k, title: 'Move page up', disabled: k === 0 }, { key: 'down', at: k, title: 'Move page down', disabled: k === model.pages.length - 1 }, { key: 'ins', at: k + 1, title: 'Insert a blank page after this one', disabled: model.pages.length >= 50 }, { key: 'dup', at: k, title: 'Duplicate this page', disabled: model.pages.length >= 50 }, { key: 'del', at: k, title: 'Delete this page', disabled: model.pages.length < 2 }] as action}<button class="icon" data-pg={action.key} data-k={action.at} title={action.title} disabled={action.disabled}><svg viewBox="0 0 20 20">{@html icons[action.key as keyof typeof icons]}</svg></button>{/each}</div></div></div>{/each}<button class="pg-add" data-pg="add" data-k={model.pages.length} title="Add a page at the end" disabled={model.pages.length >= 50}>+ Add page</button></div>
